"""Booking reference layout; static content and progressive selection controls."""
import json

def header(g):
 a,icon=g['a'],g['icon']
 return '<a class="skip" href="#main">Перейти к содержанию</a><header class="header bk-header"><div class="wrap header-inner"><div class="brand-block">'+a('home','TURRIS<span>ONLINE</span><i></i>','logo','aria-label="Туррис — главная"')+'</div><nav class="nav" id="main-nav" aria-label="Навигация бронирования">'+a('hotels','← <span>Все отели</span>','bk-back','aria-label="Все отели"')+a('manage',icon('calendar')+'<span>Моя бронь</span>','bk-manage')+'</nav><a class="header-phone" href="tel:88005054455" aria-label="Позвонить 8 800 505 44 55">'+icon('phone')+'<span>8 800 505 44 55<small>Помощь с бронированием</small></span></a><button class="demo-badge" data-demo-info>ДЕМО</button><button class="menu-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="main-nav">'+icon('menu')+'</button></div></header>'

def footer(g):
 a,icon=g['a'],g['icon']
 return '<footer class="footer bk-footer"><div class="wrap"><div class="bk-footer-grid"><div>'+a('home','TURRIS<span>ONLINE</span><i></i>','logo')+'<p>Отели в Москве</p></div><div><h3>Помощь</h3>'+a('help','Условия бронирования')+a('payment','Оплата')+a('manage','Моя бронь')+'</div><div><h3>Связаться с нами</h3><a class="bk-footer-phone" href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a><p>Поможем выбрать размещение</p></div></div><div class="footer-bottom"><span>© 2026 Туррис · Демонстрационный прототип</span>'+a('privacy','Политика конфиденциальности')+'</div></div></footer>'

def render(p,g):
 a,e,image,icon,ext,url=[g[k] for k in ('a','e','image','icon','ext','url')]
 hotels=g['HOTELS']; maps=g['MAP']; preset=p['id'].replace('_booking','') if p['id']!='booking' else ''
 title='Бронирование отелей Туррис' if not preset else 'Бронирование · '+hotels[preset]['full']
 steps='<ol class="bk-steps" aria-label="Этапы бронирования"><li aria-current="step"><span>1</span><b>Отель и номер</b></li><li><span>2</span><b>Данные и оплата<small>В модуле TravelLine</small></b></li><li><span>3</span><b>Подтверждение<small>После оформления</small></b></li></ol>'
 head='<header class="bk-heading"><h1>'+title+'</h1><p>Выберите отель, даты и гостей. Полная стоимость и условия — до подтверждения.</p></header>'+steps
 form=g['booking_form'](preset,bottom=True).replace('Любой из четырёх','Выберите отель')
 form=form.replace('Отель<select',icon('pin')+'<span>Отель</span><select').replace('Даты поездки<button',icon('calendar')+'<span>Заезд — Выезд</span><button').replace('Гости<button',icon('guest')+'<span>Гости</span><button')
 meta='<div class="bk-search-meta"><p>'+icon('document')+'<span data-search-hint>Укажите даты — покажем доступные номера и тарифы.</span></p><details class="bk-promo"><summary>Есть промокод? '+icon('chevron')+'</summary><div><label for="booking-promo">Промокод</label><div class="bk-promo-input"><input id="booking-promo" type="text" maxlength="40" autocomplete="off" placeholder="Введите код"><button type="button" data-save-promo>Сохранить</button></div><p data-promo-status role="status">Передадим код в TravelLine. Размер скидки и условия покажет модуль.</p></div></details></div>'
 form=form.replace('<button class="btn" type="submit">',meta+'<button class="btn" type="submit">')
 search='<section class="bk-search" id="booking-search" aria-label="Параметры поездки">'+form+'<p class="bk-room-context" hidden><span data-room-context></span><button type="button" data-booking-clear-room>Все категории этого отеля</button></p><p class="bk-demo-note">Цены и наличие — от TravelLine. Бронирование в модуле настоящее: проверьте условия до подтверждения.</p></section>'
 cards=''
 tags={'tverskaya':'Семейный люкс','lubyansky':'Категории с диваном','petrovsky':'Исторический особняк','tagansky':''}
 for i,h in hotels.items():
  dest=url('booking')+'?hotel='+i+'#booking-search'
  cards+='<article class="bk-hotel-card" data-booking-card="'+i+'"><div class="bk-hotel-photo">'+a(i,image(i,'Фасад отеля '+h['full']))+'<button type="button" class="bk-select-circle" data-booking-pick="'+i+'" aria-pressed="false" aria-label="Выбрать отель '+h['name']+'"><span></span></button></div><div class="bk-hotel-body"><div class="bk-card-heading"><h3>'+a(i,h['name'])+'</h3>'+('<span class="bk-tag">'+tags[i]+'</span>' if tags[i] else '')+'</div><div class="bk-card-location">'+icon('pin')+'<div><p>'+h['location']+'</p><span>'+h['address']+'</span></div></div>'+('<p class="bk-critical">В отеле нет лифта</p>' if i=='tagansky' else '')+'<div class="bk-card-actions"><a href="'+dest+'" class="btn secondary" data-booking-pick="'+i+'" data-pick-label>Выбрать отель '+icon('arrow')+'</a>'+a(i,'Об отеле ↗','text-link')+'</div></div></article>'
 cards='<section class="bk-section" id="booking-hotels"><div class="bk-section-head"><div><h2 data-booking-hotels-title>Какой адрес подходит вашей поездке?</h2><p data-booking-hotels-hint>Сравните расположение — или выберите отель на карте.</p></div><a href="#map" class="text-link">К карте ↓</a></div><button class="btn secondary bk-change-hotel" type="button" data-booking-change-hotel aria-expanded="false" aria-controls="booking-hotel-choices" hidden>Сменить отель</button><div class="bk-hotels" id="booking-hotel-choices">'+cards+'</div><p class="bk-choice-status" data-booking-choice-status aria-live="polite"></p></section>'
 stack=''
 for n,(i,h) in enumerate(hotels.items(),1):
  geo=maps['hotels'][i]
  stack+='<div class="bk-map-item"><button type="button" class="bk-map-choice" data-map-select="'+i+'" aria-pressed="false" aria-controls="map-panel-'+i+'"><span class="bk-map-number">0'+str(n)+'</span><span>'+h['name']+'</span>'+icon('chevron')+'</button><article id="map-panel-'+i+'" class="bk-map-detail" data-map-detail="'+i+'"><div class="bk-map-photo">'+image(i,'Фасад отеля '+h['full'])+'</div><p>'+icon('pin')+'<span>'+h['address']+'<small>'+h['location']+'</small></span></p>'+('<p class="bk-map-warning">В отеле нет лифта</p>' if i=='tagansky' else '')+'<a class="btn" href="'+url('booking')+'?hotel='+i+'#booking-search" data-booking-pick="'+i+'">Выбрать этот отель '+icon('arrow')+'</a>'+ext(geo['source']+'?rtext=~'+str(geo['lat'])+','+str(geo['lng']),'Построить маршрут','text-link')+'</article></div>'
 config={i:dict(geo,name=hotels[i]['name']) for i,geo in maps['hotels'].items()}
 maphtml='<section class="bk-section bk-map-section"><div class="bk-section-head"><div><h2>Выберите отель на карте</h2><p>Посмотрите, какой ближе к вашим планам.</p></div></div><div class="hotel-map bk-map" id="map" data-hotel-map data-selected="'+(preset or 'tverskaya')+'" data-tile-url="'+maps['tile_url']+'"><div class="bk-map-layout"><div class="map-stage"><div class="map-canvas" data-map-canvas role="region" aria-label="Карта четырёх отелей в Москве"></div><div class="map-toolbar"><button type="button" data-map-reset>Все отели '+icon('pin')+'</button><button type="button" data-booking-expand aria-expanded="false">⛶ <span>На весь экран</span></button></div><p class="map-status" data-map-status role="status">Загружаем карту… Адреса и маршруты доступны в карточках.</p></div><div class="bk-map-stack">'+stack+'</div></div><span class="sr-only" data-map-announcement aria-live="polite"></span><script type="application/json" data-map-config>'+json.dumps(config,ensure_ascii=False)+'</script></div></section>'
 benefits='<section class="bk-section bk-benefits"><h2>Всё важное — до подтверждения</h2><div>'+''.join('<article>'+icon(ic)+'<div><h3>'+title+'</h3><p>'+text+'</p></div></article>' for ic,title,text in [('document','Полная стоимость','За весь период и всех гостей — после выбора дат и тарифа.'),('calendar','Оплата и отмена','Сроки оплаты и правила отмены — в условиях выбранного тарифа.'),('headset','Помощь с выбором','Уточним размещение с детьми, питомцами и особые пожелания.')])+'</div></section>'
 faq=[('Когда я увижу окончательную стоимость?','После выбора дат, гостей, номера и тарифа в модуле TravelLine — до подтверждения бронирования. Стоимость зависит от выбранных условий и дополнительных услуг.',None)]+g['FAQ'][:4]+[('Как получить документы для командировки?','До оплаты сообщите отелю реквизиты плательщика и требования бухгалтерии. Порядок оплаты и выдачи документов согласуется при оформлении.','business'),('Что делать, если на нужные даты нет номеров?','Попробуйте другие даты или сравните остальные отели сети. Для помощи с подбором позвоните 8 800 505 44 55.','contacts')]
 faqhtml='<section class="bk-section bk-faq"><div><h2>Вопросы<br>о бронировании</h2><p>Поможем выбрать подходящий вариант.</p><a href="tel:88005054455">'+icon('phone')+'<span>8 800 505 44 55<small>Помощь с вашей поездкой</small></span></a></div>'+g['faqs'](faq)+'</section>'
 bottom='<section class="bk-bottom">'+icon('calendar')+'<div><h2>Ваше бронирование начинается с дат</h2><p>Выберите поездку — покажем номера и тарифы выбранного отеля.</p></div><a href="#booking-search" class="btn" data-booking-open-dates>Выбрать даты ↑</a></section>'
 return '<div class="wrap booking-page">'+head+search+'<noscript><p class="notice">Для бронирования включите JavaScript или перейдите на <a href="https://turris.online/">официальный сайт Туррис</a>.</p></noscript><div id="booking-results" aria-live="polite" tabindex="-1"></div>'+cards+maphtml+benefits+faqhtml+bottom+'</div>'
